const input = $input.first().json.body || $input.first().json;

return [{
  json: {
    job_id: `srt_${Date.now()}`,
    video_file: input.video_file,
    source_file_id: input.source_file_id,
    language: input.language || 'en',
    output_dir: input.output_dir || `/data/chakra9/subtitles`,
    temp_dir: `/tmp/chakra9/srt_${Date.now()}`
  }
}];

// Convert Whisper response to SRT format
const job = $('Prepare Job').first().json;
const whisperResponse = $input.first().json;

const segments = whisperResponse.segments || [];

function formatTime(seconds) {
  const hours = Math.floor(seconds / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 1000);
  return `${String(hours).padStart(2, '0')}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
}

const srtLines = segments.map((seg, idx) => {
  const num = idx + 1;
  const start = formatTime(seg.start);
  const end = formatTime(seg.end);
  const text = seg.text.trim();
  return `${num}\n${start} --> ${end}\n${text}\n`;
});

const srtContent = srtLines.join('\n');

// Also create VTT format
const vttLines = segments.map(seg => {
  const start = formatTime(seg.start).replace(',', '.');
  const end = formatTime(seg.end).replace(',', '.');
  return `${start} --> ${end}\n${seg.text.trim()}\n`;
});
const vttContent = `WEBVTT\n\n${vttLines.join('\n')}`;

return [{
  json: {
    job_id: job.job_id,
    srt_content: srtContent,
    vtt_content: vttContent,
    segments: segments.map(s => ({
      start: s.start,
      end: s.end,
      text: s.text.trim(),
      duration: s.end - s.start
    })),
    full_text: whisperResponse.text || segments.map(s => s.text).join(' '),
    language: whisperResponse.language || job.language,
    duration: whisperResponse.duration || (segments.length ? segments[segments.length - 1].end : 0)
  }
}];
